// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(this));
        vm.deal(address(c), amount);
        uint256 beforeBal = address(c).balance;
        vm.prank(caller);
        try c.withdraw() {
            uint256 afterBal = address(c).balance;
            assertTrue(afterBal >= beforeBal);
        } catch {
            assertTrue(address(c).balance == beforeBal);
        }
    }
}
